SELECT d.Dept_Name, e.First_Name AS Manager_Name
FROM department AS d
LEFT JOIN employee AS e ON d.Manager_ID = e.Employee_ID;

SELECT e.First_Name, e.Salary_Amount, g.Grade_Label
FROM employee AS e
JOIN salary_grade AS g ON e.Salary_Amount BETWEEN g.Min_Salary AND g.Max_Salary;

DELIMITER $$

CREATE FUNCTION GetAnnualSalary(p_employee_id INT)
RETURNS DECIMAL(10,2)
DETERMINISTIC
BEGIN
  DECLARE v_annual_salary DECIMAL(10,2);
  SELECT Salary_Amount * 12 INTO v_annual_salary
  FROM employee
  WHERE Employee_ID = p_employee_id;
  RETURN v_annual_salary;
END $$

DELIMITER ;
